module uart_tx(clk, rst, tx_start, tx_data, tx_serial, tx_busy, tx_done);
  input        clk;
  input        rst;
  input        tx_start;
  input  [7:0] tx_data;
  output reg   tx_serial;
  output reg   tx_busy;
  output reg   tx_done;

  reg [7:0] clk_count;
  reg [2:0] state;
  reg [7:0] tx_shift;
  reg [2:0] bit_index;

  localparam [2:0] ST_IDLE    = 3'b000;
  localparam [2:0] ST_START   = 3'b001;
  localparam [2:0] ST_DATA    = 3'b010;
  localparam [2:0] ST_STOP    = 3'b011;
  localparam [2:0] ST_CLEANUP = 3'b100;

  localparam [7:0] BAUD_MAX = 8'd86;

  wire baud_tick = (clk_count >= BAUD_MAX);

  always @(posedge clk) begin
    if (rst) begin
      state     <= ST_IDLE;
      clk_count <= 8'd0;
      bit_index <= 3'd0;
      tx_busy   <= 1'b0;
      tx_done   <= 1'b0;
      tx_serial <= 1'b1;
    end else begin
      tx_done <= 1'b0;

      if (state[2]) begin
        clk_count <= clk_count;
      end else begin
        case (state)
          ST_START, ST_DATA, ST_STOP: begin
            if (baud_tick)
              clk_count <= 8'd0;
            else
              clk_count <= clk_count + 8'd1;
          end
          default: begin
            clk_count <= 8'd0;
          end
        endcase
      end

      case (state)
        ST_IDLE: begin
          bit_index <= 3'd0;
          tx_serial <= 1'b1;
          tx_busy <= 1'b0;

          if (tx_start) begin
            state <= ST_START;
            tx_shift <= tx_data;
            tx_busy <= 1'b1;
          end else begin
            state <= ST_IDLE;
          end
        end

        ST_START: begin
          tx_serial <= 1'b0;
          tx_busy <= tx_busy;
          bit_index <= bit_index;

          if (baud_tick)
            state <= ST_DATA;
          else
            state <= ST_START;
        end

        ST_DATA: begin
          tx_serial <= tx_shift[bit_index];
          tx_busy <= tx_busy;

          if (baud_tick) begin
            bit_index <= bit_index + 3'd1;

            if (bit_index == 3'd7)
              state <= ST_STOP;
            else
              state <= ST_DATA;
          end else begin
            bit_index <= bit_index;
            state <= ST_DATA;
          end
        end

        ST_STOP: begin
          tx_serial <= 1'b1;
          bit_index <= bit_index;

          if (baud_tick) begin
            state <= ST_CLEANUP;
            tx_busy <= 1'b0;
            tx_done <= 1'b1;
          end else begin
            state <= ST_STOP;
            tx_busy <= tx_busy;
          end
        end

        ST_CLEANUP: begin
          state <= ST_IDLE;
          tx_serial <= tx_serial;
          tx_busy <= tx_busy;
          bit_index <= bit_index;
        end

        default: begin
          state <= ST_IDLE;
          tx_serial <= 1'b1;
          tx_busy <= 1'b0;
          bit_index <= 3'd0;
        end
      endcase
    end
  end

endmodule

